        ctx.globalAlpha = 1;
      } else {
        const r = 72 * p.s;
        const bob = Math.sin(t / 300 + it.id) * r * 0.12;
        ctx.globalAlpha = 0.25 * fade; ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.ellipse(x, p.y, r * 0.8, r * 0.22, 0, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;
