      }
    }
    if (count >= c.chain.minScore) {
      ctx.save(); ctx.font = '700 22px Unbounded, sans-serif'; ctx.textAlign = 'center'; ctx.fillStyle = GEMS[color][1];
      ctx.shadowColor = GEMS[color][1]; ctx.shadowBlur = 10;
