  const proj = (mz) => { const s = 1 / mz; return { y: HOR + (NEAR - HOR) * s, s }; };
  const laneX = (lane, s) => W / 2 + (lane - 1) * (HALF * 2 / 3) * s;
  const mzOf = (state, z) => RUNNER_MZ + (z - state.distance) / M_PER_UNIT;

  function setPalette(distance) {
