  }

  function gemPath(color, cx, cy, r) {
    ctx.beginPath();
    if (color === 'ember') { ctx.moveTo(cx, cy - r); ctx.lineTo(cx + r * 0.8, cy); ctx.lineTo(cx, cy + r); ctx.lineTo(cx - r * 0.8, cy); }
    else if (color === 'tide') ctx.arc(cx, cy, r * 0.82, 0, Math.PI * 2);
