    ctx.beginPath(); ctx.moveTo(-6, -8); ctx.lineTo(-7 + stride * 4, 2 - Math.max(0, stride) * 6); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(6, -8); ctx.lineTo(7 - stride * 4, 2 - Math.max(0, -stride) * 6); ctx.stroke();
