    ctx.fillStyle = palette.accent;
    ctx.fillRect(-11 + stride * 4, -2 - Math.max(0, stride) * 6, 8, 6); ctx.fillRect(3 - stride * 4, -2 - Math.max(0, -stride) * 6, 8, 6);
